-- MODULE REACTIK V2 - ORACLE DATABASE SCHEMA
-- Generated by Senior Software Engineer

-- 1. Catalogue des Entreprises
CREATE TABLE RX_ENTREPRISE (
    ID_ENTREPRISE   NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    NOM             VARCHAR2(100) NOT NULL UNIQUE,
    DESCRIPTION     VARCHAR2(500)
);

-- 2. Sessions de jeu
CREATE TABLE RX_SESSION (
    ID_SESSION      NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    TITRE           VARCHAR2(200) NOT NULL,
    ID_ENSEIGNANT   NUMBER NOT NULL,
    DATE_DEBUT      TIMESTAMP NOT NULL,
    DUREE_PREVUE    NUMBER CHECK (DUREE_PREVUE > 0),
    STATUT          VARCHAR2(20) DEFAULT 'BROUILLON' CHECK (STATUT IN ('BROUILLON', 'OUVERTE', 'TERMINEE'))
);

-- 3. Equipes
CREATE TABLE RX_EQUIPE (
    ID_EQUIPE       NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ID_SESSION      NUMBER NOT NULL,
    ID_ENTREPRISE   NUMBER,
    NOM_EQUIPE      VARCHAR2(100),
    VERSION         NUMBER DEFAULT 1,
    CONSTRAINT FK_EQUIPE_SESSION FOREIGN KEY (ID_SESSION) REFERENCES RX_SESSION(ID_SESSION),
    CONSTRAINT FK_EQUIPE_ENTR FOREIGN KEY (ID_ENTREPRISE) REFERENCES RX_ENTREPRISE(ID_ENTREPRISE)
);

-- 4. État global
CREATE TABLE RX_PARTIE (
    ID_PARTIE           NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ID_SESSION          NUMBER NOT NULL UNIQUE,
    PHASE_ACTUELLE      NUMBER DEFAULT 1 CHECK (PHASE_ACTUELLE BETWEEN 1 AND 8),
    CALCULATION_STATUS  VARCHAR2(20) DEFAULT 'IDLE' CHECK (CALCULATION_STATUS IN ('IDLE', 'PROCESSING')),
    EST_LANCEE          NUMBER(1) DEFAULT 0,
    CONSTRAINT FK_PARTIE_SESSION FOREIGN KEY (ID_SESSION) REFERENCES RX_SESSION(ID_SESSION)
);

-- 5. Postes
CREATE TABLE RX_POSTE (
    ID_POSTE        NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    NOM             VARCHAR2(100) NOT NULL,
    POSITION_X      NUMBER,
    POSITION_Y      NUMBER
);

-- 6. Types de Flux
CREATE TABLE RX_TYPE_FLUX (
    ID_TYPE_FLUX    NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    LIBELLE         VARCHAR2(50) NOT NULL
);

-- 7. Flux tracés
CREATE TABLE RX_FLUX (
    ID_FLUX         NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ID_EQUIPE       NUMBER NOT NULL,
    ID_POSTE_SOURCE NUMBER NOT NULL,
    ID_POSTE_CIBLE  NUMBER NOT NULL,
    ID_TYPE_FLUX    NUMBER NOT NULL,
    CONSTRAINT FK_FLUX_EQUIPE FOREIGN KEY (ID_EQUIPE) REFERENCES RX_EQUIPE(ID_EQUIPE),
    CONSTRAINT FK_FLUX_SOURCE FOREIGN KEY (ID_POSTE_SOURCE) REFERENCES RX_POSTE(ID_POSTE),
    CONSTRAINT FK_FLUX_CIBLE  FOREIGN KEY (ID_POSTE_CIBLE) REFERENCES RX_POSTE(ID_POSTE),
    CONSTRAINT FK_FLUX_TYPE   FOREIGN KEY (ID_TYPE_FLUX) REFERENCES RX_TYPE_FLUX(ID_TYPE_FLUX)
);

-- 8. Anti-Flux
CREATE TABLE RX_ANTIFLUX (
    ID_ANTIFLUX     NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    DESCRIPTION     VARCHAR2(500) NOT NULL,
    IMPACT_DELAI    NUMBER DEFAULT 0,
    IMPACT_STOCK    NUMBER DEFAULT 0
);

-- 9. Gentils-Flux
CREATE TABLE RX_GENTILFLUX (
    ID_GENTILFLUX   NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ID_ANTIFLUX     NUMBER NOT NULL,
    DESCRIPTION     VARCHAR2(500) NOT NULL,
    BONUS_DELAI     NUMBER DEFAULT 0,
    BONUS_STOCK     NUMBER DEFAULT 0,
    CONSTRAINT FK_GF_ANTIFLUX FOREIGN KEY (ID_ANTIFLUX) REFERENCES RX_ANTIFLUX(ID_ANTIFLUX)
);

-- 10. Pays
CREATE TABLE RX_PAYS (
    ID_PAYS         NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    NOM             VARCHAR2(100) NOT NULL,
    SEUIL_DELAI     NUMBER NOT NULL,
    ID_TYPE_REQUIS  NUMBER NOT NULL,
    PART_MARCHE_GAIN NUMBER NOT NULL,
    CONSTRAINT FK_PAYS_TYPE FOREIGN KEY (ID_TYPE_REQUIS) REFERENCES RX_TYPE_FLUX(ID_TYPE_FLUX)
);

-- 11. Tours
CREATE TABLE RX_TOUR (
    ID_TOUR         NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ID_PARTIE       NUMBER NOT NULL,
    NUMERO_TOUR     NUMBER NOT NULL,
    DATE_CALCUL     TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT FK_TOUR_PARTIE FOREIGN KEY (ID_PARTIE) REFERENCES RX_PARTIE(ID_PARTIE)
);

-- 12. Scores
CREATE TABLE RX_SCORE (
    ID_SCORE        NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ID_EQUIPE       NUMBER NOT NULL,
    ID_TOUR         NUMBER NOT NULL,
    DELAI_OBTENU    NUMBER,
    STOCK_RESTANT   NUMBER,
    PART_MARCHE     NUMBER,
    VALEUR_POINTS   NUMBER,
    CONSTRAINT UK_SCORE_EQ_TR UNIQUE (ID_EQUIPE, ID_TOUR),
    CONSTRAINT FK_SCORE_EQUIPE FOREIGN KEY (ID_EQUIPE) REFERENCES RX_EQUIPE(ID_EQUIPE),
    CONSTRAINT FK_SCORE_TOUR   FOREIGN KEY (ID_TOUR) REFERENCES RX_TOUR(ID_TOUR)
);

-- 13. Historique des Actions
CREATE TABLE RX_ACTION (
    ID_ACTION       NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ID_EQUIPE       NUMBER NOT NULL,
    ID_UTILISATEUR  NUMBER NOT NULL,
    PHASE_NUMERO    NUMBER NOT NULL,
    TYPE_ACTION     VARCHAR2(50) NOT NULL,
    PAYLOAD         CLOB,
    DATE_ACTION     TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT FK_ACTION_EQUIPE FOREIGN KEY (ID_EQUIPE) REFERENCES RX_EQUIPE(ID_EQUIPE)
);

-- Index de performance
CREATE INDEX IDX_RX_ACTION_EQUIPE ON RX_ACTION(ID_EQUIPE);
CREATE INDEX IDX_RX_FLUX_EQUIPE ON RX_FLUX(ID_EQUIPE);
CREATE INDEX IDX_RX_SCORE_EQUIPE ON RX_SCORE(ID_EQUIPE);
